  "confidence": 0.75,
  "anomalies": [
    {
      "category": "footprint_mismatch",
      "components": ["C13"],
      "pins": ["C13.1", "C13.2"],
      "nets": ["/NET0104", "0"],
      "observed": "C13 is specified as a 0.1uF 50V 0603 capacitor with footprint Capacitor_SMD:C_0603_1608Metric and MPN CC0603KRX7R9BB104, but its custom 'Part Description' field says '0.1uF 10% 16V Ceramic Capacitor X7R 0402 (1005 Metric)' and Field6 lists 'RM EMK105 B7104KV-F', a 0402 16V part.",
      "expected": "All metadata for a single component should agree. A 0603 50V capacitor should not carry a 0402 16V part description; the footprint and voltage rating should match the intended 0603 50V part.",
      "evidence": [
        {"source": "netlist", "quote": "(comp (ref \"C13\") (value \"0.1uF 50V\") (footprint \"Capacitor_SMD:C_0603_1608Metric\") ... (field (name \"MPN\") \"CC0603KRX7R9BB104\") ... (field (name \"Part Description\") \"0.1uF 10% 16V Ceramic Capacitor X7R 0402 (1005 Metric)\") ... (field (name \"Field6\") \"RM EMK105 B7104KV-F\")"},
        {"source": "spice", "quote": "C13 /NET0104 0 0.1uF"}
      ],
      "impact": "If the BOM or assembly process uses the conflicting 'Part Description' or Field6, a 0402 16V capacitor may be ordered or placed instead of the 0603 50V part. This would cause a footprint mismatch (0402 part on 0603 pads) and potentially a voltage-rating failure if the net exceeds 16V.",
      "confidence": 0.75
    }
  ],
  "summary": "The design files contain a metadata/footprint inconsistency on C13: its authoritative footprint and MPN specify a 0603 50V capacitor, while custom fields describe a 0402 16V part. This could lead to a sourcing or assembly error."
}

